BEGIN;
CREATE TABLE public.erp_customer_portal_settings(cafe_id uuid PRIMARY KEY REFERENCES public.cafes(id),revision integer NOT NULL DEFAULT 1,enabled boolean NOT NULL DEFAULT false,permissions jsonb NOT NULL DEFAULT '{"invoices":false,"statement":false,"appointments":false,"memberships":false,"credits":false}');
CREATE TABLE public.erp_customer_portal_links(cafe_id uuid NOT NULL,customer_id uuid NOT NULL,profile_id uuid REFERENCES public.customer_profiles(id) ON DELETE SET NULL,enabled boolean NOT NULL DEFAULT false,price_list_id uuid,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(cafe_id,customer_id),UNIQUE(cafe_id,profile_id),FOREIGN KEY(cafe_id,customer_id) REFERENCES public.bf_parties(cafe_id,id) ON DELETE CASCADE);
CREATE TABLE erp_customer_private.portal_requests(cafe_id uuid NOT NULL,request_id uuid NOT NULL,actor uuid NOT NULL,action text NOT NULL,input jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,request_id));
CREATE TABLE public.erp_customer_portal_events(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid,action text NOT NULL,actor uuid NOT NULL,at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE FUNCTION erp_customer_private.portal_settings(c uuid) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT jsonb_build_object('revision',coalesce(s.revision,0),'enabled',coalesce(s.enabled,false),'permissions',coalesce(s.permissions,'{"invoices":false,"statement":false,"appointments":false,"memberships":false,"credits":false}')) FROM(SELECT 1) q LEFT JOIN public.erp_customer_portal_settings s ON s.cafe_id=c$$;
CREATE FUNCTION public.erp_customer_options(p_cafe uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r text;cfg jsonb;can_settings boolean;BEGIN
 r:=erp_customer_private.authorize(p_cafe,'read');can_settings:=r='owner' AND erp_access_private.allowed(p_cafe,'customers','settings');cfg:=brand_finance_private.invoice_settings(p_cafe);
 RETURN jsonb_build_object('portal',erp_customer_private.portal_settings(p_cafe),'canSettings',can_settings,'canPriceGroup',r<>'auditor' AND erp_access_private.allowed(p_cafe,'customers','update'),
 'profiles',CASE WHEN can_settings THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',full_name,'phone',phone) ORDER BY full_name) FROM public.customer_profiles WHERE cafe_id=p_cafe),'[]') ELSE '[]'::jsonb END,
 'links',coalesce((SELECT jsonb_agg(jsonb_build_object('customerId',customer_id,'profileId',CASE WHEN can_settings THEN profile_id ELSE NULL END,'enabled',enabled AND profile_id IS NOT NULL,'priceListId',price_list_id,'revision',revision)) FROM public.erp_customer_portal_links WHERE cafe_id=p_cafe),'[]'),
 'priceListsEnabled',coalesce((cfg#>>'{advanced,priceListsEnabled}')::boolean,false),'priceLists',coalesce((SELECT jsonb_agg(jsonb_build_object('id',x->>'id','name',x->>'name','active',x->'active','partyIds',x->'partyIds')) FROM jsonb_array_elements(coalesce(cfg#>'{advanced,priceLists}','[]')) x),'[]'));
END $$;
CREATE FUNCTION public.erp_customer_options_write(p_cafe uuid,p_action text,p_input jsonb,p_request uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r text;old erp_customer_private.portal_requests;link public.erp_customer_portal_links;rev integer;key text;customer uuid;profile uuid;price uuid;lists jsonb;result jsonb;BEGIN
 IF p_action NOT IN('portal','link','price_group') OR p_request IS NULL OR jsonb_typeof(p_input) IS DISTINCT FROM 'object' OR octet_length(p_input::text)>8000 THEN RAISE EXCEPTION 'إجراء إعدادات العميل غير صالح';END IF;
 r:=erp_customer_private.authorize(p_cafe,CASE WHEN p_action='price_group' THEN 'update' ELSE 'settings' END);IF p_action<>'price_group' AND r<>'owner' THEN RAISE EXCEPTION 'إعداد بوابة العميل متاح للمالك' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,60412));PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe::text,67954));
 SELECT * INTO old FROM erp_customer_private.portal_requests WHERE cafe_id=p_cafe AND request_id=p_request;IF FOUND THEN IF old.actor<>auth.uid() OR old.action<>p_action OR old.input<>p_input THEN RAISE EXCEPTION 'معرف العملية مستخدم لبيانات أخرى';END IF;RETURN old.result;END IF;
 IF p_action='portal' THEN
  SELECT revision INTO rev FROM public.erp_customer_portal_settings WHERE cafe_id=p_cafe FOR UPDATE;IF coalesce(rev,0) IS DISTINCT FROM(p_input->>'revision')::integer THEN RAISE EXCEPTION 'تغيرت إعدادات البوابة' USING ERRCODE='40001';END IF;
  IF jsonb_typeof(p_input->'enabled') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_input->'permissions') IS DISTINCT FROM 'object' OR(SELECT count(*) FROM jsonb_object_keys(p_input->'permissions'))<>5 THEN RAISE EXCEPTION 'راجع صلاحيات البوابة';END IF;
  FOREACH key IN ARRAY ARRAY['invoices','statement','appointments','memberships','credits'] LOOP IF jsonb_typeof(p_input->'permissions'->key) IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'راجع صلاحيات البوابة';END IF;END LOOP;
  INSERT INTO public.erp_customer_portal_settings VALUES(p_cafe,coalesce(rev,0)+1,(p_input->>'enabled')::boolean,p_input->'permissions') ON CONFLICT(cafe_id) DO UPDATE SET revision=excluded.revision,enabled=excluded.enabled,permissions=excluded.permissions;
 ELSE
  customer:=(p_input->>'customerId')::uuid;IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=customer AND kind='customer' AND active) THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
  SELECT * INTO link FROM public.erp_customer_portal_links WHERE cafe_id=p_cafe AND customer_id=customer FOR UPDATE;rev:=coalesce(link.revision,0);IF rev IS DISTINCT FROM(p_input->>'revision')::integer THEN RAISE EXCEPTION 'تغير ربط العميل' USING ERRCODE='40001';END IF;
  IF p_action='link' THEN
   profile:=nullif(p_input->>'profileId','')::uuid;IF jsonb_typeof(p_input->'enabled') IS DISTINCT FROM 'boolean' OR((p_input->>'enabled')::boolean AND profile IS NULL) THEN RAISE EXCEPTION 'اختر حساب العميل لتفعيل دخوله';END IF;
   IF profile IS NOT NULL THEN PERFORM 1 FROM public.customer_profiles WHERE cafe_id=p_cafe AND id=profile FOR KEY SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'حساب العميل غير تابع للعلامة' USING ERRCODE='42501';END IF;END IF;
   INSERT INTO public.erp_customer_portal_links(cafe_id,customer_id,profile_id,enabled,revision) VALUES(p_cafe,customer,profile,(p_input->>'enabled')::boolean,rev+1) ON CONFLICT(cafe_id,customer_id) DO UPDATE SET profile_id=excluded.profile_id,enabled=excluded.enabled,revision=excluded.revision;
  ELSE
   price:=nullif(p_input->>'priceListId','')::uuid;lists:=brand_finance_private.invoice_settings(p_cafe)#>'{advanced,priceLists}';
   IF price IS NOT NULL AND(NOT coalesce((brand_finance_private.invoice_settings(p_cafe)#>>'{advanced,priceListsEnabled}')::boolean,false) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(lists,'[]')) x WHERE x->>'id'=price::text AND(x->>'active')::boolean AND(jsonb_array_length(coalesce(x->'partyIds','[]'))=0 OR(x->'partyIds')?customer::text))) THEN RAISE EXCEPTION 'مجموعة الأسعار غير متاحة لهذا العميل';END IF;
   INSERT INTO public.erp_customer_portal_links(cafe_id,customer_id,price_list_id,revision) VALUES(p_cafe,customer,price,rev+1) ON CONFLICT(cafe_id,customer_id) DO UPDATE SET price_list_id=excluded.price_list_id,revision=excluded.revision;
  END IF;
 END IF;
 result:=jsonb_build_object('revision',coalesce(rev,0)+1);INSERT INTO erp_customer_private.portal_requests VALUES(p_cafe,p_request,auth.uid(),p_action,p_input,result);INSERT INTO public.erp_customer_portal_events(cafe_id,customer_id,action,actor) VALUES(p_cafe,customer,p_action,auth.uid());RETURN result;
END $$;
CREATE FUNCTION public.erp_customer_default_price_list(p_cafe uuid,p_customer uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r text;result uuid;cfg jsonb;BEGIN
 r:=brand_finance_private.role_for(p_cafe);IF coalesce(r,'') NOT IN('owner','manager','accountant','auditor') THEN RAISE EXCEPTION 'غير مصرح' USING ERRCODE='42501';END IF;
 cfg:=brand_finance_private.invoice_settings(p_cafe);IF NOT coalesce((cfg#>>'{advanced,priceListsEnabled}')::boolean,false) THEN RETURN NULL;END IF;
 SELECT l.price_list_id INTO result FROM public.erp_customer_portal_links l WHERE l.cafe_id=p_cafe AND l.customer_id=p_customer AND EXISTS(SELECT 1 FROM public.bf_parties p WHERE p.cafe_id=p_cafe AND p.id=p_customer AND p.kind='customer' AND p.active) AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(cfg#>'{advanced,priceLists}','[]')) x WHERE x->>'id'=l.price_list_id::text AND(x->>'active')::boolean AND(jsonb_array_length(coalesce(x->'partyIds','[]'))=0 OR(x->'partyIds')?p_customer::text));RETURN result;
END $$;
CREATE FUNCTION public.erp_customer_services(p_cafe uuid,p_customer uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE result jsonb:='{}';s jsonb;BEGIN
 PERFORM erp_customer_private.authorize(p_cafe,'read');IF NOT EXISTS(SELECT 1 FROM public.bf_parties WHERE cafe_id=p_cafe AND id=p_customer AND kind='customer') THEN RAISE EXCEPTION 'العميل غير متاح';END IF;
 IF erp_access_private.allowed(p_cafe,'memberships','read') THEN s:=public.erp_memberships_read(p_cafe);result:=result||jsonb_build_object('memberships',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'memberships') x WHERE x->>'customerId'=p_customer::text),'[]'),'packages',s->'packages');END IF;
 IF erp_access_private.allowed(p_cafe,'credits','read') THEN s:=public.erp_credits_read(p_cafe);result:=result||jsonb_build_object('charges',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'charges') x WHERE x->>'customerId'=p_customer::text),'[]'),'usages',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'usages') x WHERE x->>'customerId'=p_customer::text),'[]'),'types',s->'types');END IF;
 IF erp_access_private.allowed(p_cafe,'insurance','read') THEN s:=public.erp_insurance_read(p_cafe);s:=jsonb_set(s,'{customers}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'customers') x WHERE x->>'id'=p_customer::text),'[]'));s:=jsonb_set(s,'{enrollments}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'enrollments') x WHERE x->>'customerId'=p_customer::text),'[]'));s:=jsonb_set(s,'{invoices}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'invoices') x WHERE x->>'customerId'=p_customer::text),'[]'));s:=jsonb_set(s,'{drafts}',coalesce((SELECT jsonb_agg(x) FROM jsonb_array_elements(s->'drafts') x WHERE x->>'customerId'=p_customer::text),'[]'));result:=result||jsonb_build_object('insurance',s);END IF;RETURN result;
END $$;
CREATE FUNCTION public.erp_customer_portal_read(p_cafe uuid,p_profile uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE l public.erp_customer_portal_links;cfg jsonb;result jsonb;customer public.bf_parties;BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.cafes WHERE id=p_cafe AND status IN('active','published') AND deleted_at IS NULL) OR NOT platform_access_private.service_enabled(p_cafe,'finance') THEN RAISE EXCEPTION 'بوابة العلامة غير متاحة' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.customer_profiles WHERE cafe_id=p_cafe AND id=p_profile) THEN RAISE EXCEPTION 'حساب العميل غير متاح' USING ERRCODE='42501';END IF;
 cfg:=erp_customer_private.portal_settings(p_cafe);SELECT * INTO l FROM public.erp_customer_portal_links WHERE cafe_id=p_cafe AND profile_id=p_profile AND enabled;SELECT * INTO customer FROM public.bf_parties WHERE cafe_id=p_cafe AND id=l.customer_id AND kind='customer' AND active;
 IF NOT(cfg->>'enabled')::boolean OR customer.id IS NULL THEN RAISE EXCEPTION 'بوابة العميل غير مفعلة لهذا الحساب' USING ERRCODE='42501';END IF;
 result:=jsonb_build_object('customer',jsonb_build_object('id',customer.id,'name',customer.name),'permissions',cfg->'permissions');
 IF(cfg#>>'{permissions,invoices}')::boolean THEN result:=result||jsonb_build_object('invoices',coalesce((SELECT jsonb_agg(jsonb_build_object('id',d.id,'number',coalesce(e.display_number,d.number::text),'date',d.created_at,'total',d.total,'outstanding',(brand_finance_private.document_state(p_cafe,d.id)->>'outstanding')::numeric,'refunded',(brand_finance_private.document_state(p_cafe,d.id)->>'refunded_total')::numeric,'document',CASE WHEN i.document_id IS NULL THEN NULL ELSE jsonb_build_object('seller',i.snapshot->'seller','currency',i.snapshot->>'currency','total',i.snapshot->'total','tax',i.snapshot->'tax','discount',i.snapshot->'discount','lines',(SELECT jsonb_agg(jsonb_build_object('name',x->>'name','quantity',x->'quantity','price',x->'price','tax',x->'tax','total',x->'total')) FROM jsonb_array_elements(i.snapshot->'lines') x)) END) ORDER BY d.created_at DESC) FROM public.bf_documents d LEFT JOIN public.bf_company_invoices i ON i.cafe_id=d.cafe_id AND i.document_id=d.id LEFT JOIN public.bf_invoice_extensions e ON e.cafe_id=d.cafe_id AND e.document_id=d.id WHERE d.cafe_id=p_cafe AND d.party_id=customer.id AND d.kind='sale'),'[]'));END IF;
 IF(cfg#>>'{permissions,statement}')::boolean THEN
  WITH rows AS(SELECT j.id,d.created_at AS date,d.number,d.kind,j.debit,j.credit,sum(j.debit-j.credit) OVER(ORDER BY d.created_at,j.created_at,j.id ROWS UNBOUNDED PRECEDING) AS balance FROM public.bf_journal j JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id AND a.kind='receivable' JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id WHERE j.cafe_id=p_cafe AND j.party_id=customer.id)
  SELECT result||jsonb_build_object('statement',coalesce(jsonb_agg(to_jsonb(rows)-'id' ORDER BY date,id),'[]'),'balance',coalesce(sum(debit-credit),0)) INTO result FROM rows;
 END IF;
 IF(cfg#>>'{permissions,appointments}')::boolean THEN result:=result||jsonb_build_object('appointments',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'startsAt',starts_at,'duration',duration,'action',action,'status',status) ORDER BY starts_at DESC) FROM public.erp_customer_appointments WHERE cafe_id=p_cafe AND customer_id=customer.id AND share_with_customer),'[]'));END IF;
 IF(cfg#>>'{permissions,memberships}')::boolean THEN result:=result||jsonb_build_object('memberships',coalesce((SELECT jsonb_agg(jsonb_build_object('id',m.id,'number',m.number,'packageName',p.name,'joinedOn',m.joined_on,'endsOn',(SELECT max(erp_membership_private.end_date(p_cafe,r.id)) FROM public.erp_membership_renewals r WHERE r.cafe_id=p_cafe AND r.membership_id=m.id AND r.status='paid'),'status',erp_membership_private.status(p_cafe,m.id)) ORDER BY m.created_at DESC) FROM public.erp_memberships m JOIN public.erp_credit_packages p ON p.cafe_id=m.cafe_id AND p.id=m.package_id WHERE m.cafe_id=p_cafe AND m.customer_id=customer.id AND NOT m.deleted),'[]'));END IF;
 IF(cfg#>>'{permissions,credits}')::boolean THEN result:=result||jsonb_build_object('credits',coalesce((SELECT jsonb_agg(jsonb_build_object('id',ch.id,'type',t.name,'unit',t.unit,'quantity',ch.quantity,'remaining',ch.quantity-coalesce((SELECT sum(a.quantity) FROM public.erp_credit_allocations a WHERE a.cafe_id=ch.cafe_id AND a.charge_id=ch.id),0),'startsOn',ch.starts_on,'expiresOn',ch.expires_on,'available',(CASE WHEN ch.source_kind='membership_renewal' THEN EXISTS(SELECT 1 FROM public.erp_membership_renewals rr LEFT JOIN public.erp_memberships mm ON mm.cafe_id=rr.cafe_id AND mm.id=rr.membership_id WHERE rr.cafe_id=p_cafe AND rr.id=ch.source_id AND rr.status='paid' AND NOT coalesce(mm.suspended OR mm.deleted,false)) ELSE NOT ch.suspended END) AND ch.starts_on<=current_date AND(ch.expires_on IS NULL OR ch.expires_on>=current_date) AND erp_membership_private.charge_allowed(p_cafe,ch.id,current_date)) ORDER BY ch.created_at DESC) FROM public.erp_credit_charges ch JOIN public.erp_credit_types t ON t.cafe_id=ch.cafe_id AND t.id=ch.type_id WHERE ch.cafe_id=p_cafe AND ch.customer_id=customer.id),'[]'));END IF;
 RETURN result;
END $$;
CREATE FUNCTION erp_customer_private.portal_audit_guard() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$BEGIN RAISE EXCEPTION 'سجل التدقيق والطلبات المؤكدة غير قابل للتعديل أو الحذف' USING ERRCODE='42501';END $$;
CREATE TRIGGER erp_customer_portal_events_immutable BEFORE UPDATE OR DELETE ON public.erp_customer_portal_events FOR EACH ROW EXECUTE FUNCTION erp_customer_private.portal_audit_guard();
CREATE TRIGGER erp_customer_portal_requests_immutable BEFORE UPDATE OR DELETE ON erp_customer_private.portal_requests FOR EACH ROW EXECUTE FUNCTION erp_customer_private.portal_audit_guard();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['erp_customer_portal_settings','erp_customer_portal_links','erp_customer_portal_events'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated,service_role',t);END LOOP;END $$;
ALTER TABLE erp_customer_private.portal_requests ENABLE ROW LEVEL SECURITY;REVOKE ALL ON erp_customer_private.portal_requests FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION erp_customer_private.portal_settings(uuid),erp_customer_private.portal_audit_guard() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.erp_customer_options(uuid),public.erp_customer_options_write(uuid,text,jsonb,uuid),public.erp_customer_services(uuid,uuid),public.erp_customer_default_price_list(uuid,uuid),public.erp_customer_portal_read(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.erp_customer_options(uuid),public.erp_customer_options_write(uuid,text,jsonb,uuid),public.erp_customer_services(uuid,uuid),public.erp_customer_default_price_list(uuid,uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.erp_customer_portal_read(uuid,uuid) TO service_role;
NOTIFY pgrst,'reload schema';
COMMIT;
